<?php
declare(strict_types=1);require_once __DIR__.'/seguridad.php';simceRequireRole(array('colegio_admin','docente'));$db=simceDatabase();$cid=simceTenantId();simceSyncStoredTests($db,$cid);$s=$db->prepare('SELECT id,titulo,curso_codigo,asignatura,ruta FROM pruebas WHERE colegio_id=:c AND activa=1 ORDER BY curso_codigo,asignatura,titulo');$s->execute(array(':c'=>$cid));$out=array();foreach($s->fetchAll()as$r){$course=$r['curso_codigo'];$subject=$r['asignatura'];if(!isset($out[$course]))$out[$course]=array();if(!isset($out[$course][$subject]))$out[$course][$subject]=array();$out[$course][$subject][]=array('id'=>(int)$r['id'],'titulo'=>$r['titulo'],'desc'=>'Prueba de '.ucfirst($subject),'archivo'=>pathinfo((string)$r['ruta'],PATHINFO_FILENAME),'url'=>'archivo_prueba.php?id='.(int)$r['id']);}simceJson($out);
